SELECT id, title, subtitle, cover, type, target, start_date AS startDate, end_date AS endDate, rule_json AS ruleJson, status FROM promotion WHERE status='ONLINE'
AND type = #{type}
ORDER BY start_date DESC

SELECT id, title, subtitle, cover, type, target, start_date AS startDate,
       end_date AS endDate, rule_json AS ruleJson, status
FROM promotion WHERE id = #{id}
